def is_prime(n: int) -> bool:
    """
    Check if the number is prime using Trial division algorithm.

    - O(sqrt(n)) time-complexity
    - O(1) space-complexity
    """
    if n <= 1:
        return False

    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

